@@ -102,6 +119,18 @@ function answerFrame(ws: WebSocket, validation: ValidationResult): void {

   const message = validation.data;
   if (message.type === 'ping') handlePing(ws, message.timestamp);
+  if (message.type === 'list_sessions') await handleListSessions(ws, session, message, sessionStore);
+}
+
+// The user is the session's, never the frame's: the validator has already dropped any userId a client sent.
+async function handleListSessions(
+  ws: WebSocket,
+  session: ChatSession,
