diff --git a/specs/hal-engine-conversation-list/spec.md b/specs/hal-engine-conversation-list/spec.md
index 2f0d190..cda4e7d 100644
--- a/specs/hal-engine-conversation-list/spec.md
+++ b/specs/hal-engine-conversation-list/spec.md
@@ -75,3 +75,4 @@ Resume gets a client back into one conversation: the id it names, or the user's
 - A store without `listFor` answers `{type: 'session_list', sessions: []}`, and a throwing `listFor` logs an error on the `ws` category and answers `{type: 'error', code: 'SERVER_ERROR'}` ([validated by: answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws](../../src/transport/conversationList.acceptance.test.ts#L129)).
 - The validator accepts an optional non-negative integer `limit` and an optional `before` cursor whose `sessionId` is 1–128 characters and whose `updatedAt` parses as a valid timestamp, rejecting any other `list_sessions` payload with `INVALID_MESSAGE` without calling `listFor` ([validated by: accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor](../../src/transport/conversationList.acceptance.test.ts#L161)).
 - The validator forwards only `limit` and a `before` of `{updatedAt, sessionId}`, so a client-supplied `userId` never reaches the handler, and each refusal names the field it refused: `limit`, `before`, `before.sessionId` or `before.updatedAt` ([validated by: accepts list_sessions with an integer limit and a cursor, dropping a client userId, and rejects malformed ones naming the field](../../src/transport/ws/validation.test.ts#L26)).
+- `createMessageHandler` takes the session store beside the orchestrator, and `createServer` hands it the one it was given, so a `list_sessions` is answered from the same store the connection authenticated against, for the session's user, with each `Date` sent as an ISO-8601 string ([validated by: answers from the store it was given, for the session user and not the frame, with ISO dates](../../src/transport/ws/messageHandler.test.ts#L873)).
diff --git a/src/transport/ws/messageHandler.test.ts b/src/transport/ws/messageHandler.test.ts
index 110f899..74aab67 100644
--- a/src/transport/ws/messageHandler.test.ts
+++ b/src/transport/ws/messageHandler.test.ts
@@ -9,6 +9,7 @@ import type {AIProvider, MessageChunk, ToolCall} from '../../types/ai.js';
 import {AIError} from '../../types/ai.js';
 import type {ChatSession, SessionEntry} from '../../types/session.js';
 import type {OutgoingMessage} from '../../types/messages.js';
+import type {SessionListOptions, SessionStore} from '../../types/sessionStore.js';
 import {PerSessionLock} from '../../shared/perSessionLock.js';
 import {deferred} from '../wsTestSupport.js';

@@ -867,3 +868,50 @@ function outcomeOf(frames: string[]): {answered: boolean; last: string | undefin
     errors: frames.filter(frame => frame.startsWith('error')),
   };
 }
+
+describe('the list_sessions frame', () => {
+  it('answers from the store it was given, for the session user and not the frame, with ISO dates', async () => {
+    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
+    const store = {
+      listFor: (userId: string | number, options?: SessionListOptions) => {
+        seen.push({userId, options});
+        return [
+          {
+            sessionId: 's9',
+            createdAt: new Date('2026-01-01T00:00:00.000Z'),
+            updatedAt: new Date('2026-01-01T00:02:00.000Z'),
+            entryCount: 2,
+          },
+        ];
+      },
+    } as unknown as SessionStore;
+    const sent: OutgoingMessage[] = [];
+    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
+    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
+    const before = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
+
+    await createMessageHandler({} as ChatOrchestrator, store)(ws, session, {
+      type: 'list_sessions',
+      limit: 5,
+      before,
+      userId: 'u2',
+    });
+
+    expect({seen, sent}).toEqual({
+      seen: [{userId: 'u1', options: {limit: 5, before}}],
+      sent: [
+        {
+          type: 'session_list',
+          sessions: [
+            {
+              sessionId: 's9',
+              createdAt: '2026-01-01T00:00:00.000Z',
+              updatedAt: '2026-01-01T00:02:00.000Z',
+              entryCount: 2,
+            },
+          ],
+        },
+      ],
+    });
+  });
+});
diff --git a/src/transport/ws/sender.ts b/src/transport/ws/sender.ts
index 93b7bc5..954dafb 100644
--- a/src/transport/ws/sender.ts
+++ b/src/transport/ws/sender.ts
@@ -1,6 +1,7 @@
 import {WebSocket} from 'ws';
 import type {SessionEntry} from '../../types/session.js';
 import type {OutgoingMessage} from '../../types/messages.js';
+import type {SessionSummary} from '../../types/sessionStore.js';

 export function sendJson(ws: WebSocket, message: OutgoingMessage): void {
   ws.send(JSON.stringify(message));
@@ -29,3 +30,16 @@ export function sendSkip(ws: WebSocket, index: number): void {
 export function sendStreamEnd(ws: WebSocket): void {
   sendJson(ws, {type: 'stream_end'});
 }
+
+// A Date does not survive JSON.stringify as a Date, so both times go on the wire as ISO-8601 strings.
+export function sendSessionList(ws: WebSocket, summaries: SessionSummary[]): void {
+  sendJson(ws, {
+    type: 'session_list',
+    sessions: summaries.map(({sessionId, createdAt, updatedAt, entryCount}) => ({
+      sessionId,
+      createdAt: createdAt.toISOString(),
+      updatedAt: updatedAt.toISOString(),
+      entryCount,
+    })),
+  });
+}

